#define main historical_main
#include "../chi2-cuda/chi2.cu"
#undef main
#include "native_reference_repaired.cuh"
#include <vector>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{unsigned char*input;float*out;std::vector<float>expected;int kind;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;const int rows=12,cols=257,ncases=3,ncontrols=9;std::vector<Case>cases;for(int kind=0;kind<=1;kind++){Case c;c.kind=kind;std::vector<unsigned char>input(rows*cols);for(int row=0;row<rows;row++)for(int col=0;col<cols;col++)input[row*cols+col]='0'+(kind==0?(row+col)%3:(row*row+col*7+row*col)%3);c.expected.resize(cols);cpu_kernel(rows,cols,ncases,ncontrols,input.data(),c.expected.data());CK(cudaMalloc(&c.input,input.size()));CK(cudaMalloc(&c.out,cols*sizeof(float)));CK(cudaMemcpy(c.input,input.data(),input.size(),cudaMemcpyHostToDevice));chi_kernel_reference_repaired<<<2,256>>>(rows,cols,ncases,ncontrols,c.input,c.out);cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;
for(int trial=1;trial<=5;trial++){double seconds=0,ma=0;std::vector<float>out;bool ok=true;for(auto&c:cases){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)chi_kernel_reference_repaired<<<2,256>>>(rows,cols,ncases,ncontrols,c.input,c.out);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<float>got(cols);CK(cudaMemcpy(got.data(),c.out,cols*sizeof(float),cudaMemcpyDeviceToHost));for(int i=0;i<cols;i++){ma=fmax(ma,fabs(got[i]-c.expected[i]));ok&=std::isfinite(got[i])&&got[i]>=0&&fabs(got[i]-c.expected[i])<=1e-4&&(c.kind!=0||got[i]==0);}out.insert(out.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"chi2_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(float),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":514,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"sum_equal_distribution_and_varied_SNP_pseudocounted_chi_square_corrected_margins\",\"jit_excluded\":true,\"internal_repeats\":%d,\"native_reference_repaired\":true,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":514,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",ma,repeat,file);}for(auto&c:cases){CK(cudaFree(c.input));CK(cudaFree(c.out));}puts(allok?"PASS":"FAIL");return allok?0:1;}
